ssive":true},{"name":"favorite_delete","check":null,"roles":"{16385}","table":"favorites","using":"((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT myevent_account_active() AS myevent_account_active))","command":"d","permissive":true},{"name":"favorite_insert","check":"((user_id = ( SELECT auth.uid() AS uid)) AND venue_catalog_private.visible(place_id))","roles":"{16385}","table":"favorites","using":null,"command":"a","permissive":true},{"name":"favorite_read","check":null,"roles":"{16385}","table":"favorites","using":"((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT myevent_account_active() AS myevent_account_active))","command":"r","permissive":true},{"name":"venue_read","check":null,"roles":"{16385}","table":"places","using":"(( SELECT myevent_account_active() AS myevent_account_active) AND ((submitted_by = ( SELECT auth.uid() AS uid)) OR venue_catalog_private.visible(id)))","command":"r","permissive":true},{"name":"revision_own","check":null,"roles":"{16385}","table":"revisions","using":"((author_id = ( SELECT auth.uid() AS uid)) AND ( SELECT myevent_account_active() AS myevent_account_active))","command":"r","permissive":true},{"name":"source_read","check":null,"roles":"{16385}","table":"sources","using":"(venue_catalog_private.visible(place_id) AND ((excerpt IS NULL) OR (EXISTS ( SELECT 1\n   FROM venue_catalog_private.places p\n  WHERE ((p.id = sources.place_id) AND (p.storage_policy = 'licensed_excerpt'::text))))))","command":"r","permissive":true}],"triggers":[],"functions":[{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_place uuid, p_favorite boolean","name":"venue_catalog_favorite","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.venue_catalog_favorite(p_place uuid, p_favorite boolean)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin if p_favorite then insert into venue_catalog_private.favorites(user_id,place_id) values(auth.uid(),p_place) on conflict do nothing;\nelse delete from venue_catalog_private.favorites where user_id=auth.uid() and place_id=p_place;end if;end $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_activity uuid, p_place uuid, p_notes jsonb","name":"venue_catalog_link_activity","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.venue_catalog_link_activity(p_activity uuid, p_place uuid, p_notes jsonb DEFAULT '{}'::jsonb)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select venue_catalog_private.link_activity(p_activity,p_place,p_notes)$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_query text, p_limit integer","name":"venue_catalog_search","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.venue_catalog_search(p_query text DEFAULT ''::text, p_limit integer DEFAULT 20)\n RETURNS TABLE(id uuid, canonical_url text, name text, address text, city text, latitude double precision, longitude double precision, provider text)\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$\n select p.id,p.canonical_url,p.name,p.address,p.city,p.latitude,p.longitude,p.provider from venue_catalog_private.places p where venue_catalog_private.visible(p.id) and (p.name ilike '%'||left(coalesce(p_query,''),100)||'%' or p.city ilike '%'||left(coalesce(p_query,''),100)||'%') order by p.name,p.id limit greatest(1,least(coalesce(p_limit,20),50))\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_data jsonb","name":"venue_catalog_submit","owner":"postgres","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.venue_catalog_submit(p_data jsonb)\n RETURNS uuid\n LANGUAGE sql\n SET search_path TO ''\nAS $function$select venue_catalog_private.submit(p_data)$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid","name":"can_read_activity","owner":"postgres","schema":"venue_catalog_private","definition":"CREATE OR REPLACE FUNCTION venue_catalog_private.can_read_activity(p_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select auth.uid() is not null and activities_private.visible(p_id) and exists(select 1 from activities_private.activities a where a.id=p_id and (a.organizer_id=auth.uid() or exists(select 1 from activities_private.members m where m.activity_id=p_id and m.user_id=auth.uid() and m.status='accepted')))\n$function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_activity uuid, p_place uuid, p_notes jsonb","name":"link_activity","owner":"postgres","schema":"venue_catalog_private","definition":"CREATE OR REPLACE FUNCTION venue_catalog_private.link_activity(p_activity uuid, p_place uuid, p_notes jsonb DEFAULT '{}'::jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if not activities_private.allowed() then raise exception 'Activités désactivées ou accès non autorisé'; end if;\n perform 1 from activities_private.activities where id=p_activity and organizer_id=auth.uid() and status='open' for update;\n if not found or not venue_catalog_private.visible(p_place) then raise exception 'Association non autorisée'; end if;\n insert into venue_catalog_private.activity_venues(activity_id,place_id,confirmed_by,organizer_notes) values(p_activity,p_place,auth.uid(),p_notes)\n on conflict(activity_id) do update set place_id=excluded.place_id,confirmed_by=excluded.confirmed_by,confirmed_at=clock_timestamp(),organizer_notes=excluded.organizer_notes;\nend $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_data jsonb","name":"submit","owner":"postgres","schema":"venue_catalog_private","definition":"CREATE OR REPLACE FUNCTION venue_catalog_private.submit(p_data jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare me uuid:=auth.uid();v_id uuid;n integer;url text:=trim(p_data->>'canonical_url');\nbegin\n if me is null or not public.myevent_account_active() then raise exception 'Compte non autorisé'; end if;\n perform pg_advisory_xact_lock(hashtextextended('venue-submit:'||me::text,0));\n select id into v_id from venue_catalog_private.places where canonical_url=url and (submitted_by=me or venue_catalog_private.visible(id));\n if found then return v_id; end if;\n select count(*) into n from venue_catalog_private.places where submitted_by=me and created_at>now()-interval '1 day';\n if n>=5 then raise exception 'Limite de propositions atteinte'; end if;\n insert into venue_catalog_private.places(canonical_url,name,address,city,latitude,longitude,submitted_by)\n values(url,trim(p_data->>'name'),p_data->>'address',p_data->>'city',(p_data->>'latitude')::double precision,(p_data->>'longitude')::double precision,me) returning id into v_id;\n return v_id;\nexception when unique_violation then raise exception 'Lieu déjà connu ou en cours de vérification';\nend $function$\n"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","args":"p_id uuid","name":"visible","owner":"postgres","schema":"venue_catalog_private","definition":"CREATE OR REPLACE FUNCTION venue_catalog_private.visible(p_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n select auth.uid() is not null and public.myevent_account_active() and exists(select 1 from venue_catalog_private.places where id=p_id and state='approved' and storage_policy in ('metadata_only','licensed_excerpt') and rights_expire_at>now())\n$function$\n"}],"relations":[{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"kind":"r","name":"activity_venues","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_identity":"d"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"kind":"i","name":"activity_venues_pkey","owner":"postgres","options":null,"force_rls":false,"persistence":"p","replica_ide